<?php
declare(strict_types=1);
require_once __DIR__.'/../config/bootstrap.php';require_once __DIR__.'/../config/governance.php';require_once __DIR__.'/../config/privacy.php';
$user=require_login($pdo);$pageTitle='Deine Daten & dein Konto';$error='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
 require_csrf();auth_rate_limit('privacy-sensitive',(string)$user['id'],10,3600);
 try{$action=post_string('action');$password=post_string('current_password',1024);
 if($action==='export'){$stream=privacy_export($pdo,(int)$user['id'],$password);header('Content-Type: application/json; charset=utf-8');header('Content-Disposition: attachment; filename="gunindex-meine-daten.json"');header('Cache-Control: no-store');fpassthru($stream);fclose($stream);exit;}
 if($action==='delete'){if(post_string('confirm_deactivation')!=='1')throw new InvalidArgumentException('Bitte die sofortige Deaktivierung ausdrücklich bestätigen.');privacy_request_deletion($pdo,(int)$user['id'],$password,post_string('reason',8000));auth_clear_session();redirect('/auth/login.php?msg=deletion_requested');}
 throw new InvalidArgumentException('Ungültige Aktion.');
 }catch(InvalidArgumentException|DomainException $e){http_response_code(422);$error=$e->getMessage();}
}
include __DIR__.'/../includes/header.php';?>
